def dirs(I,i,j):
    h,w=len(I),len(I[0]);res=[]
    for di,dj in ((0,1),(0,-1),(1,0),(-1,0)):
        k=1
        while True:
            ni,nj=i+di*k,j+dj*k
            if not(0<=ni<h and 0<=nj<w): res.append(None);break
            if I[ni][nj]==2: res.append(k);break
            k+=1
    return tuple(res)
